// Online booking API (GET): action=config gives the page its clinic info, services and days; action=slots asks the Booking Engine for free times.
// Switches: online_booking (OFF closes the page) and email_capture (shows the email field).
const q = ($('Booking API').first().json || {}).query || {};
const Z = 'Asia/Dubai';
const sw = {};
$('Booking Switch').all().forEach(function (i) { const r = i.json || {}; if (r.feature) sw[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });
const bookingOn = sw.online_booking !== false;
const emailOn = sw.email_capture !== false;
const rows = $('Get Setup').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.tab; })
  .sort(function (a, b) { return Number(a.sort || 0) - Number(b.sort || 0); });
const c = {};
rows.filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
const wa = String(c.clinic_whatsapp || '000000000000').replace(/\D/g, '');
if (!bookingOn) return [{ json: { kind: String(q.action || '') === 'slots' ? 'bad' : 'config', body: { clinic: c.clinic_name || 'BrightSmile Dental', address: c.address || '', currency: c.currency || 'AED', whatsapp: wa, services: [], days: [], slots: [], closed: true } } }];
let services = rows.filter(function (r) { return r.tab === 'price' && r.value !== '' && !isNaN(Number(r.value)) && !/emergency|طوارئ/i.test(r.name + ' ' + r.words); })
  .map(function (r) { return { name: String(r.name), price: Number(r.value), from: /^y/i.test(String(r.option || '')), minutes: Number(r.minutes) || 0 }; });
if (!services.length) services = [{ name: 'Consultation and check-up', price: 150, from: false, minutes: 30 }, { name: 'Cleaning (scale and polish)', price: 350, from: false, minutes: 30 }, { name: 'In-clinic teeth whitening', price: 1200, from: false, minutes: 90 }];

if (String(q.action || '') === 'slots') {
  const date = String(q.date || '');
  const service = String(q.service || '').slice(0, 80);
  const okService = services.some(function (s) { return s.name === service; });
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !okService) return [{ json: { kind: 'bad', body: { slots: [], error: 'Invalid date or service.' } } }];
  return [{ json: { kind: 'slots', req: { action: 'find_slots', phone: 'web', date: date, days: 1, service: service, source: 'web' } } }];
}

// config: next 14 days with open/closed from the Clinic Setup hours and holidays
const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const closed = String(c.closed_dates || '').split(/[,;\s]+/).filter(function (x) { return /^\d{4}-\d{2}-\d{2}$/.test(x); });
const today = DateTime.now().setZone(Z).startOf('day');
const ahead = Math.min(Number(c.max_days_ahead) || 60, 21);
const days = [];
for (let i = 0; i < Math.min(14, ahead); i++) {
  const d = today.plus({ days: i });
  const ymd = d.toFormat('yyyy-MM-dd');
  const h = String(c['hours_' + DAYS[d.weekday - 1]] || '').trim();
  const open = closed.indexOf(ymd) < 0 && !/closed/i.test(h);
  days.push({ date: ymd, dow: d.toFormat('ccc'), day: d.toFormat('d'), mon: d.toFormat('LLL'), open: open });
}
return [{ json: { kind: 'config', body: {
  clinic: c.clinic_name || 'BrightSmile Dental', address: c.address || 'Jumeirah, Dubai', currency: c.currency || 'AED',
  whatsapp: wa, timezone_label: 'Dubai time', email_capture: emailOn, services: services, days: days
} } }];

// Validates an online booking before it goes to the Booking Engine. Switches: online_booking, email_capture.
const sw = {};
$('Booking Switch (Book)').all().forEach(function (i) { const r = i.json || {}; if (r.feature) sw[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });
const raw = ($('Booking Submit').first().json || {}).body || {};
let b = raw;
if (typeof raw === 'string') { b = {}; String(raw).split('&').forEach(function (kv) { const p = kv.split('='); if (p[0]) b[decodeURIComponent(p[0])] = decodeURIComponent((p[1] || '').replace(/\+/g, ' ')); }); }
const lang = String(b.language || '') === 'ar' ? 'ar' : 'en';
const M = {
  closed: { en: 'Online booking is closed at the moment. Please message us on WhatsApp.', ar: 'الحجز أونلاين مقفول دلوقتي، راسلنا على واتساب.' },
  oops: { en: 'Sorry, something went wrong.', ar: 'عذراً، حصلت مشكلة.' },
  name: { en: 'Please enter your full name.', ar: 'من فضلك اكتب اسمك بالكامل.' },
  phone: { en: 'Please enter your WhatsApp number with the country code, e.g. +971 50 123 4567.', ar: 'من فضلك اكتب رقم الواتساب مع كود الدولة، مثلاً ‎+971 50 123 4567.' },
  pick: { en: 'Please choose a service, a day and a time.', ar: 'من فضلك اختار الخدمة واليوم والوقت.' },
  consent: { en: 'Please tick the box so the clinic can contact you about your appointment.', ar: 'من فضلك علّم على خانة الموافقة عشان العيادة تقدر تتواصل معاك بخصوص الموعد.' },
  email: { en: 'Please check your email address.', ar: 'من فضلك راجع الإيميل.' }
};
const bad = function (k) { return [{ json: { valid: false, body: { ok: false, message: M[k][lang] } } }]; };
if (sw.online_booking === false) return bad('closed');
const c = {};
$('Get Setup (Book)').all().forEach(function (i) { const r = i.json || {}; if (r.tab === 'clinic') c[r.name] = String(r.value || '').trim(); });
if (String(b.website || '').trim()) return bad('oops'); // bots fill the hidden field
const name = String(b.name || '').replace(/\s+/g, ' ').trim().slice(0, 80);
let phone = String(b.phone || '').replace(/\D/g, '');
if (phone.startsWith('00')) phone = phone.slice(2);
if (/^0\d{9}$/.test(phone)) phone = '971' + phone.slice(1); // UAE local 05x... number
const date = String(b.date || '');
const time = String(b.time || '');
const service = String(b.service || '').slice(0, 80);
const email = sw.email_capture === false ? '' : String(b.email || '').trim().toLowerCase().slice(0, 120);
if (name.length < 2) return bad('name');
if (phone.length < 8 || phone.length > 15) return bad('phone');
if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time) || !service) return bad('pick');
if (String(b.consent || '') !== 'yes') return bad('consent');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return bad('email');
const ownerDigits = String(c.owner_phone || '').replace(/\D/g, '');
return [{ json: { valid: true, owner: ownerDigits.length >= 8 ? ownerDigits : '000000000000', lang: lang,
  marketing: email ? { time: DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm'), name: name, phone: phone, email: email, offers_optin: String(b.offers || '') === 'yes' ? 'yes' : 'no', language: lang, source: 'booking page', service: service } : null,
  req: { action: 'book', phone: phone, start: date + ' ' + time, service: service, dentist: String(b.dentist || '').slice(0, 60), name: name, language: lang, new_or_returning: 'new', insurance: 'unknown', source: 'web' } } }];

// Turns the Booking Engine answer into a short message for the page (English or Arabic) and the owner alert.
const r = $input.first().json || {};
const chk = $('Check Service').first().json;
const req = chk.req;
const ar = chk.lang === 'ar';
const msg = String(r.response || '');
const ok = r.ok === true && /^Booked/.test(msg);
const d = DateTime.fromFormat(req.start, 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
const when = d.isValid ? (ar ? d.setLocale('ar').reconfigure({ numberingSystem: 'latn' }).toFormat('cccc d LLLL') + ' الساعة ' + d.toFormat('h:mm') + (d.hour < 12 ? ' صباحاً' : ' مساءً') : d.toFormat('cccc d LLLL') + ' at ' + d.toFormat('h:mm a')) : req.start;
const dm = msg.match(/with (Dr\.[^.]*?) at /);
const dentist = dm ? dm[1] : req.dentist;
let friendly = ar ? 'عذراً، هذا الوقت غير متاح للحجز. اختر وقتاً آخر.' : 'Sorry, that time could not be booked. Please pick another time.';
if (/already has a booking/i.test(msg)) friendly = ar ? 'لديك موعد محجوز معنا بالفعل. راسلنا على واتساب لتغييره أو للحجز لأحد أفراد العائلة.' : 'You already have an appointment with us. Please message us on WhatsApp to change it or to book for a family member.';
else if (/no longer free/i.test(msg)) friendly = ar ? 'عذراً، هذا الوقت حُجز للتو. اختر وقتاً آخر.' : 'Sorry, that time was just taken. Please pick another time.';
else if (/closed|outside opening hours|too soon|days ahead|start every/i.test(msg)) friendly = ar ? 'هذا الوقت غير متاح. اختر وقتاً من المواعيد الظاهرة.' : msg.split(' Use find_free_slots')[0];
const summaryEn = req.service + ' for ' + req.name + ', ' + (d.isValid ? d.toFormat('cccc d LLLL') + ' at ' + d.toFormat('h:mm a') : req.start) + (dentist ? ' with ' + dentist : '') + '.';
const summary = ar ? req.service + ' لـ ' + req.name + '، ' + when + (dentist ? ' مع ' + dentist : '') + '.' : summaryEn;
return [{ json: { ok: ok, summary: ok ? summary : '', message: ok ? (ar ? 'تم الحجز: ' : 'Booked: ') + summary : friendly,
  save_email: ok && !!chk.marketing, marketing: chk.marketing,
  alert: '[Noor] New online booking: ' + req.name + ' (+' + req.phone + '), ' + summaryEn + (chk.marketing ? ' Email: ' + chk.marketing.email + (chk.marketing.offers_optin === 'yes' ? ' (wants offers)' : '') + '.' : '') + ' Booked from the website.' } }];

// Audit 17 Nov 2026: only book services the clinic really offers. Matches loosely (e.g. "cleaning" -> "Cleaning (scale and polish)") so the phone agent still works; unknown services are refused.
// Also completes UAE numbers said without the country code (5x xxx xxxx -> 9715x xxx xxxx).
const it = $input.first().json;
if (!it.valid) return [{ json: it }];
const fixPhone = function (p) { let d = String(p || '').replace(/\D/g, ''); if (d.startsWith('00')) d = d.slice(2); if (/^0?5\d{8}$/.test(d)) d = '971' + d.replace(/^0/, ''); return d; };
const rows = $('Get Setup (Book)').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.tab === 'price' && r.name; });
const out = JSON.parse(JSON.stringify(it));
out.req.phone = fixPhone(out.req.phone);
if (out.marketing) out.marketing.phone = out.req.phone;
if (!rows.length) return [{ json: out }];
const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9؀-ۿ ]/g, ' ').replace(/\s+/g, ' ').trim(); };
const want = norm(it.req.service);
let hit = rows.find(function (r) { return norm(r.name) === want; });
if (!hit) hit = rows.find(function (r) { const n = norm(r.name); return want.length > 3 && (n.indexOf(want) >= 0 || want.indexOf(n) >= 0); });
if (!hit) hit = rows.find(function (r) { return String(r.words || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(function (w) { return w.length > 2; }).some(function (w) { return want.indexOf(w) >= 0; }); });
if (!hit) {
  const ar = it.lang === 'ar';
  return [{ json: { valid: false, body: { ok: false, message: ar ? 'هذه الخدمة غير متوفرة لدينا. اختر خدمة من القائمة.' : 'We do not offer that service. Please choose one from the list.', services: rows.map(function (r) { return r.name; }) } } }];
}
out.req.service = String(hit.name);
if (out.marketing) out.marketing.service = String(hit.name);
return [{ json: out }];

// Bookings made on a phone call: send the caller a WhatsApp confirmation (approved appointment_reminder template).
let b = ($('Booking Submit').first().json || {}).body || {};
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
if (String(b.channel || '') !== 'phone') return [];
const req = $('Check Service').first().json.req;
if (!req || /^000000000000/.test(String(req.phone || ''))) return [];
const ar = String(req.language || b.language || '').toLowerCase().startsWith('ar');
const d = DateTime.fromFormat(req.start, 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
if (!d.isValid) return [];
const date = d.reconfigure({ locale: ar ? 'ar' : 'en', numberingSystem: 'latn' }).toFormat('cccc d LLLL');
const time = ar ? d.toFormat('h:mm') + (d.hour < 12 ? ' صباحاً' : ' مساءً') : d.toFormat('h:mm a');
const first = String(req.name || '').trim().split(' ')[0] || (ar ? 'عزيزنا' : 'there');
return [{ json: { phone: req.phone, template: 'appointment_reminder|' + (ar ? 'ar' : 'en'), p1: first, p2: req.service, p3: date, p4: time } }];
